-- CONTANOVA core schema. Apply in Supabase SQL Editor after reviewing environment access.
create extension if not exists pgcrypto;
create table if not exists public.companies(id uuid primary key default gen_random_uuid(),name text not null,tax_id text,created_at timestamptz not null default now());
create table if not exists public.company_members(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('owner','admin','manager','cashier','seller','viewer')),created_at timestamptz not null default now(),unique(company_id,user_id));
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,address text,created_at timestamptz not null default now());
create table if not exists public.warehouses(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid references public.branches(id),name text not null,created_at timestamptz not null default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,document_number text,phone text,email text,address text,created_at timestamptz not null default now());
create table if not exists public.suppliers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,tax_id text,phone text,email text,created_at timestamptz not null default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,category_id uuid references public.categories(id),sku text,name text not null,description text,price numeric(14,2) not null default 0 check(price>=0),cost numeric(14,2) not null default 0 check(cost>=0),active boolean not null default true,created_at timestamptz not null default now(),unique(company_id,sku));
create table if not exists public.stock_balances(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,warehouse_id uuid not null references public.warehouses(id),product_id uuid not null references public.products(id),quantity numeric(14,3) not null default 0,unique(warehouse_id,product_id));
create table if not exists public.stock_movements(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,warehouse_id uuid not null references public.warehouses(id),product_id uuid not null references public.products(id),movement_type text not null,quantity numeric(14,3) not null,reference text,created_at timestamptz not null default now());
create table if not exists public.sales(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid references public.branches(id),customer_id uuid references public.customers(id),user_id uuid references auth.users(id),status text not null default 'draft',subtotal numeric(14,2) not null default 0,tax numeric(14,2) not null default 0,total numeric(14,2) not null default 0,created_at timestamptz not null default now());
create table if not exists public.sale_items(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,sale_id uuid not null references public.sales(id) on delete cascade,product_id uuid not null references public.products(id),quantity numeric(14,3) not null check(quantity>0),unit_price numeric(14,2) not null,discount numeric(14,2) not null default 0);
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,sale_id uuid references public.sales(id),method text not null,amount numeric(14,2) not null check(amount>0),provider_reference text,status text not null default 'pending',created_at timestamptz not null default now());
create table if not exists public.cash_sessions(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid references public.branches(id),user_id uuid references auth.users(id),opening_amount numeric(14,2) not null default 0,closing_amount numeric(14,2),status text not null default 'open',opened_at timestamptz not null default now(),closed_at timestamptz);
create table if not exists public.purchases(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,supplier_id uuid references public.suppliers(id),status text not null default 'draft',total numeric(14,2) not null default 0,created_at timestamptz not null default now());
create table if not exists public.online_orders(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,customer_id uuid references public.customers(id),status text not null default 'pending',payment_status text not null default 'pending',total numeric(14,2) not null default 0,created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),company_id uuid references public.companies(id) on delete cascade,user_id uuid references auth.users(id),action text not null,entity text not null,entity_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create or replace function public.is_company_member(target_company uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.company_members m where m.company_id=target_company and m.user_id=auth.uid()) $$;
do $$ declare t text; begin foreach t in array array['company_members','branches','warehouses','customers','suppliers','categories','products','stock_balances','stock_movements','sales','sale_items','payments','cash_sessions','purchases','online_orders','audit_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists company_member_access on public.%I',t); execute format('create policy company_member_access on public.%I for all using (public.is_company_member(company_id)) with check (public.is_company_member(company_id))',t); end loop; end $$;
alter table public.companies enable row level security;
drop policy if exists company_member_read on public.companies;
create policy company_member_read on public.companies for select using (public.is_company_member(id));
-- Membership writes must be performed by a trusted onboarding/admin server function, not by an unrestricted client.
